const one=(records,domain)=>records.find(x=>x?.domain===domain)??null;
export function createNFLHistoricalPregameEvidenceBundle(records=[],domains={}){const safe=records.filter(x=>x?.safeForPregameCalibration===true);return Object.freeze({bundleVersion:"FIE-NFL-HISTORICAL-PREGAME-EVIDENCE-BUNDLE-1.0.0",records:Object.freeze(safe),schedule:one(safe,domains.SCHEDULES_RESULTS),performance:one(safe,domains.TEAM_STATS),roster:one(safe,domains.WEEKLY_ROSTERS),availability:one(safe,domains.INJURIES),coaching:one(safe,domains.COACHING),scheme:one(safe,domains.SCHEME),rejectedUnsafeCount:records.length-safe.length});}
